import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialMin, uint256 newMin, uint256 lockTime, uint256 collectAmount, uint256 putAmount) public {
        // 1. Bound to reasonable ranges to keep the scenario admissible
        lockTime = bound(lockTime, 0, 1 days);
        collectAmount = bound(collectAmount, 1, 1000 ether);
        putAmount = bound(putAmount, collectAmount, 2000 ether);
        initialMin = bound(initialMin, 1, 1000 ether);
        newMin = bound(newMin, 1, 1000 ether);

        // 2. Set up an actor
        address actor = address(0x1000);
        vm.deal(actor, 5000 ether);

        // Set initial MinSum
        vm.prank(actor);
        c.SetMinSum(initialMin);

        // Initialize
        vm.prank(actor);
        c.Initialized();

        // Record MinSum after initialization
        uint256 minSumAfterInit = c.MinSum();

        // Try to change MinSum after initialization (allowed in mutant, not in reference)
        vm.prank(actor);
        try c.SetMinSum(newMin) {} catch {}

        // Put funds to have balance >= MinSum and >= collectAmount
        vm.prank(actor);
        c.Put{value: putAmount}(lockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Collect - this driver operation is the one mentioned in the difference
        vm.prank(actor);
        try c.Collect(collectAmount) {} catch {}

        // 3. Assert: MinSum after Collect must equal MinSum after initialization for the reference;
        // the bug violates this because it allowed SetMinSum to change MinSum after initialization.
        assertEq(c.MinSum(), minSumAfterInit);
    }
}

