import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _val) public {
        // initialize so that SetMinSum will revert
        c.Initialized();
        uint256 before = c.MinSum();
        // capture revert status and MinSum after call
        bool ok = true;
        try c.SetMinSum(_val) { ok = true; } catch { ok = false; }
        uint256 afterVal = c.MinSum();
        // the correct contract reverts and leaves MinSum unchanged;
        // the buggy contract updates MinSum before reverting.
        assertTrue(!ok || afterVal == before);
    }
}

