pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address player = address(0x100);

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 val1, uint256 val2) public {
        val1 = bound(val1, 1, type(uint256).max / 2 - 1);
        val2 = bound(val2, 1, type(uint256).max / 2 - 1);

        vm.prank(player);
        c.SetMinSum(0);
        vm.prank(player);
        c.Initialized();

        Attacker attacker = new Attacker(c);
        vm.deal(player, 2 ether);

        vm.prank(player);
        c.Put{value: 1 ether}(0);
        vm.prank(player);
        c.SetMinSum(val1);
        vm.warp(block.timestamp + 1);

        attacker.attack{value: 2 ether}(player, val2);

        uint256 finalMin = c.MinSum();
        assertTrue(finalMin == val1 || finalMin == val2);
    }
