contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 val1, uint256 val2) public {
        vm.assume(val1 > 0 && val2 > 0);
        vm.assume(val1 != val2);
        // Initialize the contract
        c.SetLogFile(address(this));
        c.Initialized();
        // Deploy a reentrant attacker that calls SetMinSum during Collect
        Attacker attacker = new Attacker(c, val2);
        // Fund Attacker and make it call Put
        vm.deal(address(attacker), val1);
        vm.prank(address(attacker));
        attacker.initiatePut{value: val1}();
        // Now call SetMinSum with val1
        c.SetMinSum(val1);
        // The reentrant call during Collect may have changed MinSum to val2
        // The rule: after SetMinSum(val1) returns, MinSum must be at least val1.
        assertTrue(c.MinSum() >= val1);
    }
