pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 minSum, uint256 reentrantVal, uint256 collectAmt) public {
        // Bound values to prevent arithmetic overflows within the contract under test
        bound(minSum, 1, type(uint256).max / 2);
        bound(reentrantVal, 1, type(uint256).max / 2);
        bound(collectAmt, 1, type(uint256).max / 2);

        // Ensure minSum != reentrantVal so we can detect overwrite
        vm.assume(minSum != reentrantVal);

        // Ensure we can fund the contract and set unlock times
        uint256 deposit = collectAmt;

        // Deploy the adversarial re-entrant helper
        Attacker attacker = new Attacker(c, collectAmt, reentrantVal);
        address attackerAddr = address(attacker);

        // Initialize the contract
        c.SetMinSum(100);
        c.SetLogFile(address(0));
        c.Initialized();

        // Fund attacker so it can send Ether via Put
        vm.deal(attackerAddr, deposit);

        // Attacker deposits Ether and sets unlock time so Collect will succeed in the same block
        vm.prank(attackerAddr);
        c.Put{value: deposit}(0);

        // A separate user (EOA) calls SetMinSum with a specific value
        // Since the attacker deposited, msg.sender is attacker's address and Acc[attacker].balance = deposit
        // Acc[attacker].unlockTime = block.timestamp (since block.timestamp + 0 > 0)
        // Now attacker calls Collect, which re-enters SetMinSum(reentrantVal) via the helper's receive
        address user = address(0x1234);
        vm.prank(user);
        c.SetMinSum(minSum);

        // Invariant: MinSum must equal the last value set by the user (EOA) if no re-entrant call occurred.
        // The buggy version allows the re-entrant SetMinSum(reentrantVal) during Collect to overwrite MinSum,
        // so MinSum != minSum. The correct version resists and MinSum == minSum.
        assertEq(c.MinSum(), minSum);
    }
}

