pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 deposit, uint256 collectAmt, uint256 minSum1, uint256 minSum2) public {
        // Admissible domain: deposits and collect amounts must be within reasonable balance bounds
        vm.assume(deposit >= collectAmt);
        vm.assume(deposit <= type(uint128).max);
        vm.assume(collectAmt > 0);
        vm.assume(minSum1 > 0);
        // minSum2 must differ from minSum1, otherwise the reentrant call makes no difference
        vm.assume(minSum1 != minSum2);

        // Deploy reentrant attacker that calls SetMinSum during Collect
        ReentrantAttacker attacker = new ReentrantAttacker(c, minSum2);

        // Setup: initialize contract, set LogFile to a dummy address (can be attacker itself, no impact)
        c.SetMinSum(minSum1);
        c.SetLogFile(address(attacker));
        c.Initialized();

        // Fund attacker and have it deposit
        vm.deal(address(attacker), deposit);
        attacker.deposit{value: deposit}();

        // Warp past unlock time to allow collect
        vm.warp(block.timestamp + 1 days);

        // Attacker triggers reentrant Collect which will call SetMinSum(minSum2) back
        attacker.attack(collectAmt);

        // After all calls settle (original SetMinSum and reentrant SetMinSum),
        // the contract's MinSum must equal minSum1 (the last non-reentrant top-level SetMinSum call)
        // under the correct contract; the buggy modifier allows the reentrant call to overwrite it.
        assertTrue(c.MinSum() == minSum1);
    }
}

contract ReentrantAttacker {
    C public c;
    uint256 public targetMinSum;
    bool private attacking;

    constructor(C _c, uint256 _targetMinSum) {
        c = _c;
        targetMinSum = _targetMinSum;
    }

    function deposit() external payable {
        c.Put{value: msg.value}(0);
    }

    function attack(uint256 amount) external {
        attacking = true;
        c.Collect(amount);
    }

    receive() external payable {
        if (attacking) {
            attacking = false;
            // Reentrant call – change MinSum to a different value
            c.SetMinSum(targetMinSum);
        }
    }
}

