pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 collectAmt, uint256 minSumVal, uint256 reentrantVal) public {
        vm.assume(lockTime > 0);
        vm.assume(collectAmt > 0 && collectAmt <= minSumVal);
        vm.assume(minSumVal > 0);
        vm.assume(reentrantVal != minSumVal);

        // Deploy re-entrant attacker that calls SetMinSum during Collect
        ReenterAttacker attacker = new ReenterAttacker();
        vm.deal(address(attacker), minSumVal);

        // Initialize the contract
        vm.prank(address(this));
        c.Initialized();

        // Fund the attacker's account in C with a Put
        vm.prank(address(attacker));
        c.Put{value: minSumVal}(lockTime);

        // Set MinSum to the initial value
        vm.prank(address(attacker));
        c.SetMinSum(minSumVal);

        // Warp past unlock time so Collect is allowed
        vm.warp(block.timestamp + lockTime + 1);

        // Prepare re-entrant attack: attacker will call SetMinSum(reentrantVal) during Collect
        attacker.prepare(address(c), reentrantVal, collectAmt);

        // Call SetMinSum as the attacker; the re-entrant call will overwrite MinSum with reentrantVal
        vm.prank(address(attacker));
        c.SetMinSum(minSumVal);

        // After the dust settles, MinSum must be either minSumVal or reentrantVal (both top-level calls).
        // The reference modifier prevents re-entrancy, so MinSum must equal the last top-level SetMinSum argument: minSumVal.
        // The buggy modifier allows re-entrancy, so MinSum can equal reentrantVal, which differs from minSumVal.
        assertEq(c.MinSum(), minSumVal);
    }
}

contract ReenterAttacker {
    C internal target;
    uint256 internal reenterVal;
    uint256 internal collectAmt;

    function prepare(address _target, uint256 _reenterVal, uint256 _collectAmt) external {
        target = C(_target);
        reenterVal = _reenterVal;
        collectAmt = _collectAmt;
    }

    receive() external payable {
        // Re-entrant call to overwrite MinSum with a different value
        target.SetMinSum(reenterVal);
    }

    function trigger() external {
        target.Collect(collectAmt);
    }
}

